func TestCXCallMng(t *testing.T) {
	var manager CXCallMng
	manager.CXCallMngInit(2, false)
	CXCallMngTestCheck(t, &manager, "init", 0, 2)

	first := manager.CXCallAlloc()
	manager.CXCallGet(first).Line = 11
	second := manager.CXCallAlloc()
	manager.CXCallGet(second).Line = 22
	CXCallMngTestCheck(t, &manager, "two allocs", 2, 2)
	if objmodel.GidTypeTag(int64(first)) != CXCallGidTypeTag || objmodel.GidGeneration(int64(first)) != objmodel.GidGenerationFirst {
		t.Fatalf("first Gid %#x has the wrong tag or generation", int64(first))
	}
	if manager.CXCallGet(first).Line != 11 || manager.CXCallGet(second).Line != 22 {
		t.Fatal("Get does not return the allocated objects")
	}

	manager.CXCallRelease(first)
	CXCallMngTestCheck(t, &manager, "release", 1, 2)
	third := manager.CXCallAlloc()
	CXCallMngTestCheck(t, &manager, "reuse", 2, 2)
	if objmodel.GidIndex(int64(third)) != objmodel.GidIndex(int64(first)) {
		t.Fatal("Alloc did not reuse the released slot")
	}
	if objmodel.GidGeneration(int64(third)) != objmodel.GidGeneration(int64(first))+1 {
		t.Fatalf("generation %d after one release, want %d", objmodel.GidGeneration(int64(third)), objmodel.GidGeneration(int64(first))+1)
	}
	if manager.CXCallGet(third).Line != 0 {
		t.Fatal("a reused slot is not zeroed")
	}

	manager.CXCallRelease(second)
	manager.CXCallRelease(third)
	CXCallMngTestCheck(t, &manager, "release all", 0, 2)
	manager.CXCallMngTeardown()
	CXCallMngTestCheck(t, &manager, "teardown", 0, 0)
}

